1	import 'dart:async';
2	
3	import 'package:fake_async/fake_async.dart';
4	import 'package:flutter_test/flutter_test.dart';
5	import 'package:fpdart/fpdart.dart';
6	
7	import 'package:cerne/core/failure/failure.dart';
8	import 'package:cerne/features/export/domain/entities/export_download_format.dart';
9	import 'package:cerne/features/export/domain/entities/export_job_state.dart';
10	import 'package:cerne/features/export/domain/repositories/export_repository.dart';
11	import 'package:cerne/features/export/domain/services/download_opener.dart';
12	import 'package:cerne/features/export/presentation/cubit/export_job_cubit.dart';
13	
14	/// A controllable fake (same hand-written convention `ChatCubit`'s own
15	/// test suite uses for `ChatRepository`) rather than a mocktail stub —
16	/// [getStatusResults] is a queue consumed one entry per `getStatus` call,
17	/// repeating its last entry once exhausted, so a test only has to queue
18	/// the few stages it cares about.
19	class _FakeExportRepository implements ExportRepository {
20	  Either<Failure, String> createJobResult = right('job-1');
21	  final List<({DateTime periodStart, DateTime periodEnd})> createJobCalls = [];
22	
23	  final List<Either<Failure, ExportJobState>> getStatusResults = [];
24	  final List<String> getStatusCalls = [];
25	
26	  /// Review finding (verification-gap layer) — when set, the next
27	  /// `getStatus` call doesn't resolve until this completer completes,
28	  /// letting a test hold one poll tick's own repository call open across
29	  /// a second (and third) `Timer.periodic` tick firing underneath it —
30	  /// the exact overlap `ExportJobCubit._pollInFlight` exists to prevent.
31	  /// Consumed once, then cleared, so only the call it was set for waits.
32	  Completer<void>? delayNextGetStatus;
33	
34	  @override
35	  Future<Either<Failure, String>> createJob({
36	    required DateTime periodStart,
37	    required DateTime periodEnd,
38	  }) async {
39	    createJobCalls.add((periodStart: periodStart, periodEnd: periodEnd));
40	    return createJobResult;
41	  }
42	
43	  @override
44	  Future<Either<Failure, ExportJobState>> getStatus(String jobId) async {
45	    // Recorded before the gate below so a test can observe "the call was
46	    // made and is still in flight" — not just "the call has resolved".
47	    getStatusCalls.add(jobId);
48	    final gate = delayNextGetStatus;
49	    delayNextGetStatus = null;
50	    if (gate != null) {
51	      await gate.future;
52	    }
53	    if (getStatusResults.isEmpty) {
54	      return right(const ExportJobState.generating());
55	    }
56	    final index = (getStatusCalls.length - 1).clamp(
57	      0,
58	      getStatusResults.length - 1,
59	    );
60	    return getStatusResults[index];
61	  }
62	
63	  /// spec-7-2 — queued per-call, same consume-one-entry convention as
64	  /// [getStatusResults]; defaults to a success URL when nothing is queued,
65	  /// so a test that only cares about the opener side doesn't also have to
66	  /// stub this.
67	  final List<Either<Failure, String>> getDownloadUrlResults = [];
68	  final List<({String jobId, ExportDownloadFormat format})>
69	  getDownloadUrlCalls = [];
70	
71	  /// Review finding (code review, patch item 3) — same gate convention as
72	  /// [delayNextGetStatus], for [ExportJobCubit._downloadInFlight]'s own
73	  /// overlap test.
74	  Completer<void>? delayNextGetDownloadUrl;
75	
76	  @override
77	  Future<Either<Failure, String>> getDownloadUrl(
78	    String jobId, {
79	    required ExportDownloadFormat format,
80	  }) async {
81	    getDownloadUrlCalls.add((jobId: jobId, format: format));
82	    final gate = delayNextGetDownloadUrl;
83	    delayNextGetDownloadUrl = null;
84	    if (gate != null) {
85	      await gate.future;
86	    }
87	    if (getDownloadUrlResults.isEmpty) {
88	      return right('https://storage.example.com/signed');
89	    }
90	    return getDownloadUrlResults.removeAt(0);
91	  }
92	}
93	
94	/// spec-7-2 — [DownloadOpener]'s own hand-written fake, same convention as
95	/// [_FakeExportRepository]: [openResult] configures the next (and every
96	/// subsequent, until changed) call's return value, [openCalls] records
97	/// every URL actually passed through. [throwOnOpen], when set, makes
98	/// [open] throw instead of returning — covering [ExportJobCubit._download]'s
99	/// own try/catch around this call (review finding, code review patch
100	/// item 5): the real `UrlLauncherDownloadOpener` already catches
101	/// internally and never throws, but nothing on the [DownloadOpener]
102	/// contract itself enforces that for a future implementation.
103	class _FakeDownloadOpener implements DownloadOpener {
104	  bool openResult = true;
105	  Object? throwOnOpen;
106	  final List<String> openCalls = [];
107	
108	  @override
109	  Future<bool> open(String url) async {
110	    openCalls.add(url);
111	    final error = throwOnOpen;
112	    if (error != null) {
113	      throw error;
114	    }
115	    return openResult;
116	  }
117	}
118	
119	void main() {
120	  late _FakeExportRepository repository;
121	  late _FakeDownloadOpener downloadOpener;
122	  late ExportJobCubit cubit;
123	
124	  final periodStart = DateTime.utc(2026, 1, 1);
125	  final periodEnd = DateTime.utc(2026, 1, 31);
126	
127	  // Slightly over the cubit's own fixed 2s poll cadence (Design Notes).
128	  // Review finding (blind-hunter layer) — every test below runs inside
129	  // `fakeAsync` (`async.elapse(...)`), so this is virtual time, not real
130	  // wall-clock delay: the whole suite no longer takes ~48s to run.
131	  const onePoll = Duration(milliseconds: 2100);
132	
133	  setUp(() {
134	    repository = _FakeExportRepository();
135	    downloadOpener = _FakeDownloadOpener();
136	    cubit = ExportJobCubit(repository, downloadOpener);
137	  });
138	
139	  tearDown(() async {
140	    if (!cubit.isClosed) {
141	      await cubit.close();
142	    }
143	  });
144	
145	  test(
146	    'initial state is preparing (Pendente) before start() is ever called',
147	    () {
148	      expect(cubit.state, isA<ExportJobPreparing>());
149	    },
150	  );
151	
152	  group('start — Create job', () {
153	    test('happy path: stores jobId, keeps Pendente, returns true '
154	        '(sheet may open)', () {
155	      fakeAsync((async) {
156	        bool? started;
157	        unawaited(
158	          cubit
159	              .start(periodStart: periodStart, periodEnd: periodEnd)
160	              .then((value) => started = value),
161	        );
162	        async.flushMicrotasks();
163	
164	        expect(started, isTrue);
165	        expect(repository.createJobCalls.single.periodStart, periodStart);
166	        expect(repository.createJobCalls.single.periodEnd, periodEnd);
167	        expect(cubit.state, isA<ExportJobPreparing>());
168	      });
169	    });
170	
171	    test('Create fails: emits error, returns false (sheet never opens), '
172	        'and never starts polling', () {
173	      fakeAsync((async) {
174	        repository.createJobResult = left(
175	          const Failure.networkOffline(message: 'offline'),
176	        );
177	
178	        bool? started;
179	        unawaited(
180	          cubit
181	              .start(periodStart: periodStart, periodEnd: periodEnd)
182	              .then((value) => started = value),
183	        );
184	        async.flushMicrotasks();
185	
186	        expect(started, isFalse);
187	        expect(cubit.state, isA<ExportJobError>());
188	        expect((cubit.state as ExportJobError).failure, isA<NetworkOffline>());
189	
190	        // No poll ever fires for a job that was never created.
191	        async.elapse(onePoll);
192	        expect(repository.getStatusCalls, isEmpty);
193	      });
194	    });
195	
196	    test('spec-7-3: Create rejects synchronously with EXPORT_EMPTY_PERIOD '
197	        '-> emits emptyPeriod and returns true (sheet opens directly on '
198	        '"Período vazio"), and never starts polling', () {
199	      fakeAsync((async) {
200	        repository.createJobResult = left(
201	          const Failure.exportEmptyPeriod(message: 'Nenhum registro.'),
202	        );
203	
204	        bool? started;
205	        unawaited(
206	          cubit
207	              .start(periodStart: periodStart, periodEnd: periodEnd)
208	              .then((value) => started = value),
209	        );
210	        async.flushMicrotasks();
211	
212	        expect(started, isTrue);
213	        expect(cubit.state, isA<ExportJobEmptyPeriod>());
214	
215	        // No jobId was ever stored, so no poll ever fires either.
216	        async.elapse(onePoll);
217	        expect(repository.getStatusCalls, isEmpty);
218	      });
219	    });
220	  });
221	
222	  group('polling (I/O matrix rows)', () {
223	    test('Processando: the first poll tick moves Pendente -> Processando, '
224	        'and keeps polling (non-terminal)', () {
225	      fakeAsync((async) {
226	        repository.getStatusResults.add(
227	          right(const ExportJobState.generating()),
228	        );
229	
230	        unawaited(cubit.start(periodStart: periodStart, periodEnd: periodEnd));
231	        async.flushMicrotasks();
232	        async.elapse(onePoll);
233	
234	        expect(cubit.state, isA<ExportJobGenerating>());
235	        expect(repository.getStatusCalls, hasLength(1));
236	      });
237	    });
238	
239	    test('Dados prontos: data_ready maps to ExportJobDataReady and keeps '
240	        'polling (non-terminal — the narrative may still be processing '
241	        'underneath it, spec-7-2)', () {
242	      fakeAsync((async) {
243	        repository.getStatusResults.add(
244	          right(const ExportJobState.dataReady()),
245	        );
246	
247	        unawaited(cubit.start(periodStart: periodStart, periodEnd: periodEnd));
248	        async.flushMicrotasks();
249	        async.elapse(onePoll);
250	
251	        expect(cubit.state, isA<ExportJobDataReady>());
252	
253	        final callsAtDataReady = repository.getStatusCalls.length;
254	        async.elapse(onePoll);
255	        expect(repository.getStatusCalls.length, greaterThan(callsAtDataReady));
256	      });
257	    });
258	
259	    test('Concluído: done with narrativeStatus done maps to '
260	        'ExportOutcome.narrativeReady, and polling stops (terminal)', () {
261	      fakeAsync((async) {
262	        repository.getStatusResults.add(
263	          right(const ExportJobState.done(ExportOutcome.narrativeReady)),
264	        );
265	
266	        unawaited(cubit.start(periodStart: periodStart, periodEnd: periodEnd));
267	        async.flushMicrotasks();
268	        async.elapse(onePoll);
269	
270	        expect(cubit.state, isA<ExportJobDone>());
271	        expect(
272	          (cubit.state as ExportJobDone).outcome,
273	          ExportOutcome.narrativeReady,
274	        );
275	
276	        final callsAtTerminal = repository.getStatusCalls.length;
277	        async.elapse(onePoll);
278	        expect(repository.getStatusCalls.length, callsAtTerminal);
279	      });
280	    });
281	
282	    test('Narrativa falhou/pulada: done with a failed/skipped narrative maps '
283	        'to ExportOutcome.narrativeUnavailable', () {
284	      fakeAsync((async) {
285	        repository.getStatusResults.add(
286	          right(const ExportJobState.done(ExportOutcome.narrativeUnavailable)),
287	        );
288	
289	        unawaited(cubit.start(periodStart: periodStart, periodEnd: periodEnd));
290	        async.flushMicrotasks();
291	        async.elapse(onePoll);
292	
293	        expect(
294	          (cubit.state as ExportJobDone).outcome,
295	          ExportOutcome.narrativeUnavailable,
296	        );
297	      });
298	    });
299	
300	    test(
301	      'Erro: a job-level error is terminal/non-retryable — polling stops',
302	      () {
303	        fakeAsync((async) {
304	          repository.getStatusResults.add(
305	            right(
306	              const ExportJobState.error(
307	                Failure.aiGenerationTimeout(message: 'boom'),
308	              ),
309	            ),
310	          );
311	
312	          unawaited(
313	            cubit.start(periodStart: periodStart, periodEnd: periodEnd),
314	          );
315	          async.flushMicrotasks();
316	          async.elapse(onePoll);
317	
318	          expect(cubit.state, isA<ExportJobError>());
319	
320	          final callsAtTerminal = repository.getStatusCalls.length;
321	          async.elapse(onePoll);
322	          expect(repository.getStatusCalls.length, callsAtTerminal);
323	        });
324	      },
325	    );
326	
327	    test('Período vazio: emptyPeriod is terminal — polling stops, maps to '
328	        'the adjust-period copy rather than a generic error', () {
329	      fakeAsync((async) {
330	        repository.getStatusResults.add(
331	          right(const ExportJobState.emptyPeriod()),
332	        );
333	
334	        unawaited(cubit.start(periodStart: periodStart, periodEnd: periodEnd));
335	        async.flushMicrotasks();
336	        async.elapse(onePoll);
337	
338	        expect(cubit.state, isA<ExportJobEmptyPeriod>());
339	
340	        final callsAtTerminal = repository.getStatusCalls.length;
341	        async.elapse(onePoll);
342	        expect(repository.getStatusCalls.length, callsAtTerminal);
343	      });
344	    });
345	
346	    test('a transient poll failure (Left) is swallowed, never surfaced — '
347	        'the next tick simply tries again', () {
348	      fakeAsync((async) {
349	        repository.getStatusResults
350	          ..add(left(const Failure.networkTimeout(message: 'timeout')))
351	          ..add(right(const ExportJobState.generating()));
352	
353	        unawaited(cubit.start(periodStart: periodStart, periodEnd: periodEnd));
354	        async.flushMicrotasks();
355	        async.elapse(onePoll);
356	        // First tick failed transiently — state is unchanged (still
357	        // Pendente), not flipped to a false terminal error.
